class Shape {
    int area() { return 0; }
}
class Rectangle extends Shape {
    int width;
    int height;
    Rectangle(int width, int height) {
        this.width = width;
        this.height = height;
    }
    @Override int area() {
        return width * height;
    }
}
public class Main {
    public static void main(String[] args) {
        Shape shape = new Rectangle(3, 4);
        System.out.println(shape.area());
    }
}

